-- Safety-critical flags for a nerve conduction study / EMG result, independent of the axes.

CREATE TABLE nerve_conduction_study_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    nerve_conduction_study_test_result_grade_id UUID NOT NULL
        REFERENCES nerve_conduction_study_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-technique',
            'unexpected-finding',
            'missing-impression',
            'missing-measurement',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_nerve_conduction_study_test_result_grade_flag_grade_id
    ON nerve_conduction_study_test_result_grade_flag(nerve_conduction_study_test_result_grade_id);

CREATE TRIGGER trigger_nerve_conduction_study_test_result_grade_flag_updated_at
    BEFORE UPDATE ON nerve_conduction_study_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

